import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentActivities({ user, selectedSubject: initialSubject, setSelectedSubject: setParentSubject }) {
  const [activities, setActivities] = useState([]);
  const studentSubjects = user?.subjects 
    ? (Array.isArray(user.subjects) ? user.subjects : String(user.subjects).split(',').map(s => s.trim()).filter(Boolean)) 
    : ["Mathematics", "Science", "English"];

  const [selectedSubject, setSelectedSubject] = useState(initialSubject || studentSubjects[0] || 'Mathematics');
  const [activityLessonFilter, setActivityLessonFilter] = useState('All');
  const [activityTypeFilter, setActivityTypeFilter] = useState('All');
  const [activityAnswers, setActivityAnswers] = useState({});

  const [isSubmitted, setIsSubmitted] = useState(false);
  const [score, setScore] = useState(null);

  useEffect(() => {
    axios.get('http://localhost:8082/api/lesson-activities-list')
      .then(res => setActivities(res.data || []))
      .catch(() => setActivities([]));
  }, []);

  const cleanTxt = (str) => (str || '').replace(/\$|\{|\}/g, '');
  const parseNum = (str) => parseInt((str || '').replace(/\D/g, '')) || 0;

  const getActivityType = (act) => {
    const type = (act.question_type || '').toLowerCase();
    if (type.includes('true') || type.includes('tf')) return 'True/False';
    if (type.includes('mcq')) return 'MCQ';
    if (type.includes('short')) return 'Short Answer';

    const optA = (act.option_a || '').toUpperCase().trim();
    if (optA === 'TRUE' || !act.option_c) return 'True/False';
    if (act.option_c || act.option_d) return 'MCQ';
    return 'Short Answer';
  };

  const handleSubjectChange = (sub) => {
    setSelectedSubject(sub);
    if (setParentSubject) setParentSubject(sub);
    handleReset();
  };

  const subjectActivities = activities.filter(a => (a.subject || a.subject_name || '').toLowerCase().includes(selectedSubject.toLowerCase()));
  const activityLessons = Array.from(new Set(subjectActivities.map(a => a.lesson_name?.trim()).filter(Boolean))).sort((a, b) => parseNum(b) - parseNum(a));

  const filteredActivities = subjectActivities.filter(a => {
    if (activityLessonFilter !== 'All' && (a.lesson_name || '').toLowerCase() !== activityLessonFilter.toLowerCase()) return false;
    if (activityTypeFilter !== 'All' && getActivityType(a) !== activityTypeFilter) return false;
    return true;
  });

  const handleSubmit = () => {
    if (filteredActivities.length === 0) return;

    if (Object.keys(activityAnswers).length < filteredActivities.length) {
      if (!window.confirm("ඔබ සියලුම ප්‍රශ්න සඳහා පිළිතුරු ලබා දී නැත. Submit කරන්නද?")) {
        return;
      }
    }

    let calculatedScore = 0;
    filteredActivities.forEach((act) => {
      const userAnswer = (activityAnswers[act.id] || '').toString().trim().toLowerCase();
      const correctAnswer = (act.correct_answer || act.answer || '').toString().trim().toLowerCase();

      if (userAnswer && correctAnswer && userAnswer === correctAnswer) {
        calculatedScore += 1;
      }
    });

    setScore(calculatedScore);
    setIsSubmitted(true);
  };

  const handleReset = () => {
    setActivityAnswers({});
    setIsSubmitted(false);
    setScore(null);
  };

  // Helper function: වැරදි උත්තරය විතරක් රතු පාටින් පෙන්වීමට
  const getOptionStyle = (act, optionKey) => {
    const userAnswer = (activityAnswers[act.id] || '').toString().trim().toLowerCase();
    const correctAnswer = (act.correct_answer || act.answer || '').toString().trim().toLowerCase();
    const currentOpt = optionKey.toString().trim().toLowerCase();

    // Submit කර නැති විට
    if (!isSubmitted) {
      const isSelected = userAnswer === currentOpt;
      return {
        border: isSelected ? '2px solid #145c2e' : '1px solid #cbd5e1',
        backgroundColor: isSelected ? '#d1fae5' : '#ffffff',
        color: isSelected ? '#145c2e' : '#475569',
        fontWeight: isSelected ? 'bold' : 'normal'
      };
    }

    // Submit කළ පසු (වැරදි උත්තරය විතරක් රතු පාටින්, අනෙක්වා සාමාන්‍ය පරිදි)
    const isUserChoice = userAnswer === currentOpt;
    const isCorrect = correctAnswer === currentOpt;

    if (isUserChoice && !isCorrect) {
      return {
        border: '2px solid #dc2626',
        backgroundColor: '#fee2e2',
        color: '#b91c1c',
        fontWeight: 'bold'
      };
    }

    // ළමයා තෝරපු එක හරි නම් හෝ වෙනත් ඒවා (හරි උත්තරය පෙන්වන්නේ නැත)
    return {
      border: isUserChoice ? '2px solid #145c2e' : '1px solid #e2e8f0',
      backgroundColor: isUserChoice ? '#d1fae5' : '#ffffff',
      color: isUserChoice ? '#145c2e' : '#475569',
      fontWeight: isUserChoice ? 'bold' : 'normal'
    };
  };

  return (
    <div style={styles.whiteBox}>
      <div style={styles.tabHeader}>
        <div>
          <h2 style={{ margin: 0, fontSize: '20px', color: '#145c2e', fontWeight: 'bold' }}>
            🧩 Lesson Activities - <span style={{ color: '#16a34a' }}>{selectedSubject}</span>
          </h2>
          <p style={{ margin: '4px 0 0 0', fontSize: '13px', color: '#64748b' }}>Interactive practice tasks curated for {selectedSubject}</p>
        </div>
        
        <div style={{ display: 'flex', gap: '8px' }}>
          {studentSubjects.map(sub => (
            <button key={sub} onClick={() => handleSubjectChange(sub)} style={{ ...styles.filterTab, backgroundColor: selectedSubject === sub ? '#145c2e' : '#f1f5f9', color: selectedSubject === sub ? '#fff' : '#475569' }}>
              {sub}
            </button>
          ))}
        </div>
      </div>

      <div style={{ ...styles.filterBar, justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{ fontSize: '13px', fontWeight: 'bold', color: '#145c2e' }}>📘 Select Lesson:</span>
          <select value={activityLessonFilter} onChange={(e) => { setActivityLessonFilter(e.target.value); handleReset(); }} style={styles.selectInput}>
            <option value="All">All Lessons</option>
            {activityLessons.map(les => <option key={les} value={les}>{les}</option>)}
          </select>
        </div>

        <div style={{ display: 'flex', gap: '8px' }}>
          {['All', 'True/False', 'MCQ', 'Short Answer'].map(t => (
            <button 
              key={t} 
              onClick={() => { setActivityTypeFilter(t); handleReset(); }}
              style={{ ...styles.pillBtn, backgroundColor: activityTypeFilter === t ? '#145c2e' : '#fff', color: activityTypeFilter === t ? '#fff' : '#475569', border: '1px solid #cbd5e1' }}
            >
              {t === 'All' ? '📋 All Types' : t}
            </button>
          ))}
        </div>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '18px' }}>
        {filteredActivities.map((act, index) => {
          const type = getActivityType(act);

          return (
            <div key={act.id} style={styles.activityCard}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
                <span style={{ fontSize: '14.5px', fontWeight: 'bold', color: '#145c2e' }}>
                  Question {String(index + 1).padStart(2, '0')}
                </span>
                <span style={{ fontSize: '11.5px', backgroundColor: '#ecfdf5', color: '#15803d', border: '1px solid #bbf7d0', padding: '3px 10px', borderRadius: '12px', fontWeight: 'bold' }}>
                  {type}
                </span>
              </div>

              <p style={{ fontSize: '15px', margin: '0 0 18px 0', color: '#1e293b', fontWeight: '500', lineHeight: '1.6' }}>
                {cleanTxt(act.question_text)}
              </p>

              {/* TRUE / FALSE */}
              {type === 'True/False' && (
                <div style={{ display: 'flex', gap: '14px', maxWidth: '420px' }}>
                  {['TRUE', 'FALSE'].map(opt => {
                    const st = getOptionStyle(act, opt);
                    const isUserChoice = (activityAnswers[act.id] || '').toString().trim().toLowerCase() === opt.toLowerCase();
                    const isWrong = isSubmitted && st.backgroundColor === '#fee2e2';

                    return (
                      <button
                        key={opt}
                        disabled={isSubmitted}
                        onClick={() => setActivityAnswers({ ...activityAnswers, [act.id]: opt })}
                        style={{
                          flex: 1, padding: '12px', borderRadius: '10px', cursor: isSubmitted ? 'default' : 'pointer', fontSize: '13.5px',
                          ...st
                        }}
                      >
                        {opt === 'TRUE' ? '✅ TRUE' : '❌ FALSE'}
                        {isWrong && ' (Wrong)'}
                      </button>
                    );
                  })}
                </div>
              )}

              {/* MCQ */}
              {type === 'MCQ' && (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', maxWidth: '750px' }}>
                  {[
                    { k: 'A', txt: act.option_a }, { k: 'B', txt: act.option_b },
                    { k: 'C', txt: act.option_c }, { k: 'D', txt: act.option_d }
                  ].filter(o => Boolean(o.txt)).map(o => {
                    const st = getOptionStyle(act, o.k);
                    const isWrong = isSubmitted && st.backgroundColor === '#fee2e2';

                    return (
                      <div 
                        key={o.k}
                        onClick={() => !isSubmitted && setActivityAnswers({ ...activityAnswers, [act.id]: o.k })}
                        style={{
                          padding: '12px 16px', borderRadius: '10px', cursor: isSubmitted ? 'default' : 'pointer', display: 'flex', alignItems: 'center', gap: '10px', fontSize: '14px',
                          ...st
                        }}
                      >
                        <span style={{ backgroundColor: isWrong ? '#dc2626' : '#f1f5f9', color: isWrong ? '#fff' : '#64748b', borderRadius: '50%', width: '26px', height: '26px', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px', fontWeight: 'bold' }}>
                          {o.k}
                        </span>
                        {cleanTxt(o.txt)}
                        {isWrong && <span style={{ marginLeft: 'auto', fontSize: '12px' }}>✗ Wrong</span>}
                      </div>
                    );
                  })}
                </div>
              )}

              {/* SHORT ANSWER */}
              {type === 'Short Answer' && (
                <div>
                  <input 
                    type="text" 
                    disabled={isSubmitted}
                    placeholder="Type your final answer here..."
                    value={activityAnswers[act.id] || ''}
                    onChange={(e) => setActivityAnswers({ ...activityAnswers, [act.id]: e.target.value })}
                    style={{ 
                      ...styles.inputLarge, 
                      maxWidth: '600px',
                      border: isSubmitted ? (getOptionStyle(act, activityAnswers[act.id]).border) : '1px solid #cbd5e1',
                      backgroundColor: isSubmitted ? (getOptionStyle(act, activityAnswers[act.id]).backgroundColor) : '#fff'
                    }}
                  />
                </div>
              )}
            </div>
          );
        })}

        {filteredActivities.length === 0 && (
          <p style={{ color: '#94a3b8', fontStyle: 'italic', padding: '30px', textAlign: 'center', fontSize: '14px' }}>
            No activities published for <b>{activityLessonFilter !== 'All' ? activityLessonFilter : selectedSubject}</b> yet.
          </p>
        )}

        {/* SUBMIT / SCORE CARD SECTION */}
        {filteredActivities.length > 0 && (
          <div style={{ marginTop: '20px', textAlign: 'center' }}>
            {!isSubmitted ? (
              <button onClick={handleSubmit} style={styles.submitBtn}>
                🚀 Submit Answers & View Results
              </button>
            ) : (
              <div style={styles.scoreCard}>
                <h3 style={{ margin: '0 0 8px 0', fontSize: '18px', color: '#145c2e' }}>🎉 Activity Completed!</h3>
                <p style={{ margin: '0 0 14px 0', fontSize: '16px', fontWeight: 'bold', color: '#1e293b' }}>
                  Your Score: <span style={{ color: score === filteredActivities.length ? '#16a34a' : '#d97706', fontSize: '20px' }}>{score}</span> / {filteredActivities.length}
                  <span style={{ marginLeft: '10px', fontSize: '14px', color: '#64748b' }}>
                    ({Math.round((score / filteredActivities.length) * 100)}%)
                  </span>
                </p>
                <button onClick={handleReset} style={styles.resetBtn}>
                  🔄 Try Again
                </button>
              </div>
            )}
          </div>
        )}

      </div>
    </div>
  );
}

const styles = {
  whiteBox: { backgroundColor: '#fff', padding: '24px', borderRadius: '18px', border: '1px solid #e2e8f0', boxShadow: '0 4px 14px rgba(0,0,0,0.03)' },
  tabHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #f1f5f9', paddingBottom: '16px', marginBottom: '20px' },
  filterBar: { display: 'flex', alignItems: 'center', gap: '12px', backgroundColor: '#f8fafc', padding: '10px 16px', borderRadius: '12px', border: '1px solid #e2e8f0', marginBottom: '22px' },
  activityCard: { backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderLeft: '5px solid #145c2e', borderRadius: '12px', padding: '20px', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' },
  pillBtn: { padding: '8px 18px', borderRadius: '20px', fontSize: '13px', fontWeight: 'bold', cursor: 'pointer', transition: 'all 0.2s' },
  filterTab: { border: 'none', padding: '7px 16px', borderRadius: '20px', fontSize: '12.5px', fontWeight: 'bold', cursor: 'pointer', transition: 'all 0.2s' },
  selectInput: { padding: '7px 14px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '12.5px', fontWeight: 'bold', backgroundColor: '#fff', color: '#1e293b', cursor: 'pointer' },
  inputLarge: { padding: '11px 15px', borderRadius: '10px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '13.5px', backgroundColor: '#fff', width: '100%', boxSizing: 'border-box' },
  submitButton: { backgroundColor: '#145c2e', color: '#ffffff', padding: '14px 36px', border: 'none', borderRadius: '12px', fontSize: '15px', fontWeight: 'bold', cursor: 'pointer', boxShadow: '0 4px 12px rgba(20, 92, 46, 0.25)', transition: 'all 0.2s' },
  submitBtn: { backgroundColor: '#145c2e', color: '#ffffff', padding: '14px 36px', border: 'none', borderRadius: '12px', fontSize: '15px', fontWeight: 'bold', cursor: 'pointer', boxShadow: '0 4px 12px rgba(20, 92, 46, 0.25)', transition: 'all 0.2s' },
  scoreCard: { backgroundColor: '#f0fdf4', border: '2px solid #bbf7d0', padding: '20px', borderRadius: '14px', display: 'inline-block', minWidth: '320px' },
  resetBtn: { backgroundColor: '#145c2e', color: '#fff', padding: '8px 20px', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13px' }
};
